127	    /**
128	     * Normalise a raw telephone number to E.164 form.
129	     *
130	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
131	     * code are kept when present; otherwise country code '+61' is assumed and a
132	     * single leading '0' is dropped from the national digits. The result must have
133	     * between 8 and 15 digits after the '+'.
134	     *
135	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
136	     * national-number length is additionally validated against that country code:
137	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
138	     * length is wrong for its country is rejected.
139	     *
140	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
141	     */
142	    static String toE164(String raw) {
143	        if (raw == null) {
144	            return null;
145	        }
146	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
147	        String digits;
148	        boolean explicitCountryCode;
149	        if (cleaned.startsWith("+")) {
150	            digits = cleaned.substring(1);
151	            explicitCountryCode = true;
152	        } else {
153	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
154	            digits = "61" + national;
155	            explicitCountryCode = false;
156	        }
157	        if (!digits.matches("[0-9]{8,15}")) {
158	            return null;
159	        }
160	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
161	            return null;
162	        }
163	        return "+" + digits;
164	    }
165	
166	    /**
167	     * Validate the national-number length of an E.164 number (its digits without the
168	     * leading '+') against the requirement for its country code: country code '+61'
169	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
170	     * without a configured length requirement are accepted unchanged.
171	     */
172	    private static boolean hasValidNationalLength(String digits) {
173	        if (digits.startsWith("61")) {
174	            return digits.length() - "61".length() == 9;
175	        }
176	        if (digits.startsWith("1")) {
177	            return digits.length() - "1".length() == 10;
178	        }
179	        return true;
180	    }
181	
182	    /**
183	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
184	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
185	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
186	     * input normalises to the empty string.
187	     */
188	    private static String normaliseIdentity(String value) {
189	        if (value == null) {
190	            return "";
191	        }
192	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
193	    }
194	
195	    /**
196	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
197	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
198	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
199	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
200	     * that is both stored and used for every address comparison.
201	     */
202	    static String normaliseAddress(String value) {
203	        if (value == null) {
204	            return "";
205	        }
206	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
207	        if (collapsed.isEmpty()) {
208	            return "";
209	        }
210	        String[] tokens = collapsed.split(" ");
211	        StringBuilder result = new StringBuilder();
212	        for (int i = 0; i < tokens.length; i++) {
213	            if (i > 0) {
214	                result.append(' ');
215	            }
216	            result.append(expandAddressAbbreviation(tokens[i]));
217	        }
218	        return result.toString();
219	    }
220	
221	    /**
222	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
223	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
224	     * returned unchanged.
225	     */
226	    private static String expandAddressAbbreviation(String token) {
227	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
228	        return switch (core) {
229	            case "ST" -> "STREET";
230	            case "RD" -> "ROAD";
231	            case "AVE" -> "AVENUE";
232	            default -> token;
233	        };
234	    }
235	
236	    /**
237	     * Derive the stable, shared household identifier for owners in the same household: the first 12
238	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
239	     * so every owner with the same last name and postcode resolves to the same value regardless of
240	     * the order in which they were created.
241	     */
242	    private static String householdId(String lastNameKey, String postcode) {
243	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
244	    }
245	
246	    /**
247	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
248	     * name and postcode). An owner without a postcode has no household peers and counts as a household
249	     * of one.
250	     */
251	    private int householdSize(Owner owner) {
252	        if (owner.getPostcode() == null) {
253	            return 1;
254	        }
255	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
256	        return (int) this.clinicService.findAllOwners().stream()
257	            .filter(existing -> existing.getPostcode() != null
258	                && householdId.equals(
259	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
260	            .count();
261	    }
262	
263	    /**
264	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
265	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
266	     * postcode has no household peers, so this is empty.
267	     */
268	    private List<Owner> otherHouseholdMembers(Owner owner) {
269	        if (owner.getPostcode() == null) {
270	            return List.of();
271	        }
272	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
273	        return this.clinicService.findAllOwners().stream()
274	            .filter(existing -> !existing.isDeleted())
275	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
276	            .filter(existing -> existing.getPostcode() != null
277	                && householdId.equals(
278	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
279	            .toList();
280	    }
281	
282	    /**
283	     * The owner's membership level after applying the household ceiling: the natural level derived
284	     * from the owner's membership points, capped at one above the current maximum membership level
285	     * among the owner's existing household members. With no existing household member no cap applies.
286	     * Assumes the owner's household size has already been populated.
287	     */
288	    private Integer cappedMembershipLevel(Owner owner) {
289	        Integer natural = ownerMapper.formatMembershipLevel(owner);
290	        if (natural == null) {
291	            return null;
292	        }
293	        List<Owner> members = otherHouseholdMembers(owner);
294	        if (members.isEmpty()) {
295	            return natural;
296	        }
297	        int maxMemberLevel = 0;
298	        for (Owner member : members) {
299	            member.setHouseholdSize(householdSize(member));
300	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
301	            if (memberLevel != null) {
302	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
303	            }
304	        }
305	        return Math.min(natural, maxMemberLevel + 1);
306	    }
307	
308	    /**
309	     * Build an owner's derived duplicate-detection identity key as
310	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
311	     * component contributes the empty string, and the email is lower-cased so the comparison is
312	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
313	     */
314	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
315	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
316	        String emailKey = email == null ? "" : email.toLowerCase();
317	        String household = householdId == null ? "" : householdId;
318	        return telephone + "|" + emailKey + "|" + household;
319	    }
320	
321	    /**
322	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
323	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
324	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
325	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
326	     * only on the owner's own region and identity, not on how many owners already exist.
327	     */
328	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
329	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
330	    }
331	
332	    /**
333	     * De-duplicate a computed customer code against the codes already assigned to existing owners:
334	     * when {@code code} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
335	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
336	     */
337	    private String deduplicateCustomerCode(String code) {
338	        Set<String> existing = this.clinicService.findAllOwners().stream()
339	            .map(Owner::getCustomerCode)
340	            .filter(Objects::nonNull)
341	            .collect(Collectors.toSet());
342	        if (!existing.contains(code)) {
343	            return code;
344	        }
345	        int n = 2;
346	        while (existing.contains(code + "-" + n)) {
347	            n++;
348	        }
349	        return code + "-" + n;
350	    }
351	
352	    /**
353	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
354	     */
355	    private static String hash8(String input) {
356	        return hashHex(input, 8, true);
357	    }
358	
359	    /**
360	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
361	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
362	     */
363	    private static String hashHex(String input, int length, boolean upperCase) {
364	        try {
365	            byte[] digest = MessageDigest.getInstance("SHA-256")
366	                .digest(input.getBytes(StandardCharsets.UTF_8));
367	            StringBuilder sb = new StringBuilder(digest.length * 2);
368	            for (byte b : digest) {
369	                sb.append(String.format("%02x", b));
370	            }
371	            String hex = sb.substring(0, length);
372	            return upperCase ? hex.toUpperCase() : hex;
373	        }
374	        catch (java.security.NoSuchAlgorithmException e) {
375	            throw new IllegalStateException(e);
376	        }
377	    }
378	
379	    /**
380	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
381	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
382	     * fixed city-to-region table, else {@code "UNKNOWN"}.
383	     */
384	    private static String region(String postcode, String city) {
385	        String fromPostcode = regionForPostcode(postcode);
386	        return fromPostcode != null ? fromPostcode : regionForCity(city);
387	    }
388	
389	    /**
390	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
391	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
392	     */
393	    private static String regionForPostcode(String postcode) {
394	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
395	            return null;
396	        }
397	        int value = Integer.parseInt(postcode);
398	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
399	            int[] range = entry.getValue();
400	            if (value >= range[0] && value <= range[1]) {
401	                return entry.getKey();
402	            }
403	        }
404	        return null;
405	    }
406	
407	    /**
408	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
409	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
410	     * weekday; ordinary weekday dates are returned unchanged.
411	     */
412	    static LocalDate toBusinessDay(LocalDate date) {
413	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
414	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
415	            || PUBLIC_HOLIDAYS.contains(date)) {
416	            date = date.plusDays(1);
417	        }
418	        return date;
419	    }
420	
421	    /**
422	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
423	     * using the same per-day accumulation path as the daily create-limit rule.
424	     */
425	    private long ownersCreatedOn(LocalDate registrationDate) {
426	        LocalDate day = toBusinessDay(registrationDate);
427	        return this.clinicService.findAllOwners().stream()
428	            .map(Owner::getRegistrationDate)
429	            .filter(existing -> existing != null)
430	            .map(OwnerRestControllerV1::toBusinessDay)
431	            .filter(day::equals)
432	            .count();
433	    }
434	
435	    /**
436	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
437	     * postcode against the owner's city region.
438	     */
439	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
440	        "NSW", new int[] {2000, 2099},
441	        "VIC", new int[] {3000, 3099},
442	        "QLD", new int[] {4000, 4099});
443	
444	    /**
445	     * Resolve an owner's region from the city using the fixed city-to-region table
446	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
447	     * when the city is not listed.
448	     */
449	    private static String regionForCity(String city) {
450	        return switch (city == null ? "" : city) {
451	            case "Sydney" -> "NSW";
452	            case "Melbourne" -> "VIC";
453	            case "Brisbane" -> "QLD";
454	            default -> "UNKNOWN";
455	        };
456	    }
457	
458	    /**
459	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
460	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
461	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
462	     */
463	    private static boolean isPostcodeValid(String postcode, String city) {
464	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
465	            return false;
466	        }
467	        int[] range = REGION_POSTCODES.get(regionForCity(city));
468	        if (range == null) {
469	            return true;
470	        }
471	        int value = Integer.parseInt(postcode);
472	        return value >= range[0] && value <= range[1];
473	    }
474	
475	    /**
476	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
477	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
478	     */
479	    private static boolean isDisposableEmailDomain(String email) {
480	        if (email == null) {
481	            return false;
482	        }
483	        int at = email.lastIndexOf('@');
484	        if (at < 0 || at == email.length() - 1) {
485	            return false;
486	        }
487	        String domain = email.substring(at + 1).toLowerCase();
488	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
489	    }
