491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
494	        Collection<Owner> owners;
495	        if (lastName != null) {
496	            owners = this.clinicService.findOwnerByLastName(lastName);
497	        } else {
498	            owners = this.clinicService.findAllOwners();
499	        }
500	        if (owners.isEmpty()) {
501	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
502	        }
503	        owners.forEach(owner -> owner.setHouseholdSize(householdSize(owner)));
504	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
505	    }
506	
507	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
508	    @Override
509	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
510	        Owner owner = this.clinicService.findOwnerById(ownerId);
511	        if (owner == null) {
512	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
513	        }
514	        owner.setHouseholdSize(householdSize(owner));
515	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
516	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
517	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
518	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
519	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
520	    }
521	
522	    /**
523	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
524	     * request carries no such header (or there is no active servlet request). A blank value is treated
525	     * as absent.
526	     */
527	    private static String currentIdempotencyKey() {
528	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
529	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
530	            return null;
531	        }
532	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
533	        return (key == null || key.isBlank()) ? null : key;
534	    }
535	
536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Override
538	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
539	        String idempotencyKey = currentIdempotencyKey();
540	        if (idempotencyKey != null) {
541	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
542	            if (existingId != null) {
543	                Owner existing = this.clinicService.findOwnerById(existingId);
544	                if (existing != null) {
545	                    existing.setHouseholdSize(householdSize(existing));
546	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
547	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
548	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
549	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
550	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
551	                }
552	            }
553	        }
554	        String telephone = toE164(ownerFieldsDto.getTelephone());
555	        if (telephone == null) {
556	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
557	        }
558	        String email = ownerFieldsDto.getEmail();
559	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
560	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
561	        }
562	        if (isDisposableEmailDomain(email)) {
563	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
564	        }
565	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
566	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
567	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
568	        // normalized addressLine2 appended after a single space when present.
569	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
570	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
571	        boolean structuredAddress = !addressLine1.isEmpty();
572	        String address;
573	        if (structuredAddress) {
574	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
575	        } else {
576	            address = normaliseAddress(ownerFieldsDto.getAddress());
577	        }
578	        if (address.isEmpty()) {
579	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
580	        }
581	        String postcode = ownerFieldsDto.getPostcode();
582	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
583	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
584	        }
585	        if (ownerFieldsDto.getRegistrationDate() != null
586	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
587	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
588	        }
589	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
590	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
591	        LocalDate registrationDate = toBusinessDay(effectiveDate);
592	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
593	            .map(Owner::getRegistrationDate)
594	            .filter(existing -> existing != null)
595	            .map(OwnerRestControllerV1::toBusinessDay)
596	            .filter(registrationDate::equals)
597	            .count();
598	        if (ownersCreatedThatDay >= 100) {
599	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
600	        }
601	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
602	        long ownersInCity = this.clinicService.findAllOwners().stream()
603	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
604	            .count();
605	        if (ownersInCity >= 50) {
606	            return new ResponseEntity<>(HttpStatus.CONFLICT);
607	        }
608	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
609	        // The household is deterministically keyed on (normalized last name, postcode): every owner
610	        // with a postcode belongs to the household identified by this computed id, and owners sharing
611	        // a last name and postcode share it automatically. A new owner may join an existing household;
612	        // the household ceiling below (rather than a hard rejection) governs its membership level.
613	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
614	        String identityKey = identityKey(telephone, email, householdId);
615	        boolean identityInUse = this.clinicService.findAllOwners().stream()
616	            .filter(existing -> !existing.isDeleted())
617	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
618	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
619	        if (identityInUse) {
620	            return new ResponseEntity<>(HttpStatus.CONFLICT);
621	        }
622	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
623	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
624	            .filter(existing ->
625	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
626	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
627	            .count();
628	        HttpHeaders headers = new HttpHeaders();
629	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
630	        owner.setNamesakeCount(namesakeCount);
631	        owner.setAddress(address);
632	        if (structuredAddress) {
633	            owner.setAddressLine1(addressLine1);
634	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
635	        } else {
636	            owner.setAddressLine1(null);
637	            owner.setAddressLine2(null);
638	        }
639	        owner.setTelephone(telephone);
640	        owner.setEmail(email == null ? null : email.toLowerCase());
641	        owner.setRegistrationDate(registrationDate);
642	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
643	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
644	        owner.setHouseholdId(householdId);
645	        // A created owner is never flagged as a suspected duplicate: a lone owner has no household
646	        // peer, and a same-household owner can only be created by declaring 'sharesHousehold', which
647	        // makes it an intentional household member rather than a suspected duplicate.
648	        owner.setPossibleDuplicateOf(null);
649	        this.clinicService.saveOwner(owner);
650	        if (idempotencyKey != null) {
651	            this.idempotentCreations.put(idempotencyKey, owner.getId());
652	        }
653	        owner.setHouseholdSize(householdSize(owner));
654	        Integer membershipLevel = cappedMembershipLevel(owner);
655	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
656	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
657	            membershipLevel, ownerMapper.formatMembershipNumber(owner));
658	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
659	        ownerDto.setMembershipLevel(membershipLevel);
660	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
661	        headers.setLocation(UriComponentsBuilder.newInstance()
662	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
663	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
664	    }
665	
666	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
667	    @Override
668	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
669	        String telephone = toE164(ownerFieldsDto.getTelephone());
670	        if (telephone == null) {
671	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
672	        }
673	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
674	        if (currentOwner == null) {
675	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
676	        }
677	        String email = ownerFieldsDto.getEmail();
678	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
679	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
680	        }
681	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
682	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
683	        if (!addressLine1.isEmpty()) {
684	            currentOwner.setAddressLine1(addressLine1);
685	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
686	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
687	        } else {
688	            currentOwner.setAddressLine1(null);
689	            currentOwner.setAddressLine2(null);
690	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
691	        }
692	        currentOwner.setCity(ownerFieldsDto.getCity());
693	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
694	        currentOwner.setLastName(ownerFieldsDto.getLastName());
695	        currentOwner.setTelephone(telephone);
696	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
697	        this.clinicService.saveOwner(currentOwner);
698	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
699	    }
700	
701	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
702	    @Transactional
703	    @Override
704	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
705	        Owner owner = this.clinicService.findOwnerById(ownerId);
706	        if (owner == null) {
707	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
708	        }
709	        // Soft delete: flag the owner deleted and retain the record so it can still be read back.
710	        owner.setDeleted(true);
711	        this.clinicService.saveOwner(owner);
712	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
713	    }
714	
715	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
716	    @Override
717	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
718	        Owner owner = this.clinicService.findOwnerById(ownerId);
719	        if (owner == null) {
720	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
721	        }
722	        HttpHeaders headers = new HttpHeaders();
723	        Pet pet = petMapper.toPet(petFieldsDto);
724	        owner.setId(ownerId);
725	        pet.setOwner(owner);
726	        pet.getType().setName(null);
727	        this.clinicService.savePet(pet);
728	        PetDto petDto = petMapper.toPetDto(pet);
729	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
730	            .buildAndExpand(pet.getId()).toUri());
731	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
732	    }
733	
734	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
735	    @Override
736	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
737	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
738	        if (currentOwner != null) {
739	            Pet currentPet = this.clinicService.findPetById(petId);
740	            if (currentPet != null) {
741	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
742	                currentPet.setName(petFieldsDto.getName());
743	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
744	                this.clinicService.savePet(currentPet);
745	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
746	            }
747	        }
748	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
749	    }
750	
751	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
752	    @Override
753	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
754	        HttpHeaders headers = new HttpHeaders();
755	        Visit visit = visitMapper.toVisit(visitFieldsDto);
756	        Pet pet = new Pet();
757	        pet.setId(petId);
758	        visit.setPet(pet);
759	        this.clinicService.saveVisit(visit);
760	        VisitDto visitDto = visitMapper.toVisitDto(visit);
761	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
762	            .buildAndExpand(visit.getId()).toUri());
763	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
764	    }
765	
766	
767	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
768	    @Override
769	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
770	        Owner owner = this.clinicService.findOwnerById(ownerId);
771	        if (owner != null) {
772	            Pet pet = owner.getPet(petId);
773	            if (pet != null) {
774	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
775	            }
776	        }
777	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
778	    }
779	}
