17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
24	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
25	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
28	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
30	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
34	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
35	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
36	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
37	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
38	    @Mapping(target = "bulkSignupWarning", ignore = true)
39	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives an owner's age band from the birth date, computed against the registration date
44	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
45	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
46	     * {@code null} when no birth date is present, so the field is omitted from the response.
47	     */
48	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
49	        if (owner == null || owner.getBirthDate() == null) {
50	            return null;
51	        }
52	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
53	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
54	        if (age < 18) {
55	            return OwnerDto.AgeBandEnum.MINOR;
56	        }
57	        if (age < 65) {
58	            return OwnerDto.AgeBandEnum.ADULT;
59	        }
60	        return OwnerDto.AgeBandEnum.SENIOR;
61	    }
62	
63	    /**
64	     * Derives an owner's duplicate-detection identity key as
65	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
66	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
67	     * telephone, email or household id contributes the empty string in its position.
68	     */
69	    default String formatIdentityKey(Owner owner) {
70	        if (owner == null) {
71	            return null;
72	        }
73	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
74	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
75	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
76	        return telephone + "|" + email + "|" + householdId;
77	    }
78	
79	    /**
80	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
81	     * (non-null and non-blank), otherwise {@code PHONE}.
82	     */
83	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
88	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
89	    }
90	
91	    /**
92	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
93	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
94	     * When the customer code is absent it falls back to resolving the region directly, preferring the
95	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
96	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
97	     * {@code "UNKNOWN"} when neither resolves.
98	     */
99	    default String formatLocality(Owner owner) {
100	        if (owner == null) {
101	            return null;
102	        }
103	        String code = owner.getCustomerCode();
104	        if (code != null) {
105	            int dash = code.indexOf('-');
106	            if (dash > 0) {
107	                return code.substring(0, dash);
108	            }
109	        }
110	        String fromPostcode = regionForPostcode(owner.getPostcode());
111	        if (fromPostcode != null) {
112	            return fromPostcode;
113	        }
114	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
115	            case "Sydney" -> "NSW";
116	            case "Melbourne" -> "VIC";
117	            case "Brisbane" -> "QLD";
118	            default -> "UNKNOWN";
119	        };
120	    }
121	
122	    /**
123	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
124	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
125	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
126	     * so the field is omitted from the response.
127	     */
128	    default String formatTimezone(Owner owner) {
129	        if (owner == null) {
130	            return null;
131	        }
132	        return switch (formatLocality(owner)) {
133	            case "NSW" -> "Australia/Sydney";
134	            case "VIC" -> "Australia/Melbourne";
135	            case "QLD" -> "Australia/Brisbane";
136	            default -> null;
137	        };
138	    }
139	
140	    /**
141	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
142	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
143	     * no known range, signalling that the caller should fall back to the city-to-region table.
144	     */
145	    private String regionForPostcode(String postcode) {
146	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
147	            return null;
148	        }
149	        int value = Integer.parseInt(postcode);
150	        if (value >= 2000 && value <= 2099) {
151	            return "NSW";
152	        }
153	        if (value >= 3000 && value <= 3099) {
154	            return "VIC";
155	        }
156	        if (value >= 4000 && value <= 4099) {
157	            return "QLD";
158	        }
159	        return null;
160	    }
161	
162	    /**
163	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
164	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
165	     * owner's tenure exceeds 365 days.
166	     */
167	    default Integer formatMembershipPoints(Owner owner) {
168	        if (owner == null) {
169	            return null;
170	        }
171	        int points = 0;
172	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
173	        if (hasEmail) {
174	            points += 2;
175	        }
176	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
177	        if (unique) {
178	            points += 1;
179	        }
180	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
181	        if (largeHousehold) {
182	            points += 2;
183	        }
184	        boolean tenured = owner.getRegistrationDate() != null
185	            && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1;
186	        if (tenured) {
187	            points += 3;
188	        }
189	        return points;
190	    }
191	
192	    /**
193	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
194	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
195	     */
196	    default Integer formatMembershipLevel(Owner owner) {
197	        if (owner == null) {
198	            return null;
199	        }
200	        int points = formatMembershipPoints(owner);
201	        if (points <= 1) {
202	            return 1;
203	        }
204	        if (points <= 3) {
205	            return 2;
206	        }
207	        if (points <= 5) {
208	            return 3;
209	        }
210	        return 4;
211	    }
212	
213	    /**
214	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
215	     * customer code. Returns {@code null} when the customer code is absent.
216	     */
217	    default Integer formatCheckDigit(Owner owner) {
218	        if (owner == null || owner.getCustomerCode() == null) {
219	            return null;
220	        }
221	        String code = owner.getCustomerCode();
222	        int sum = 0;
223	        boolean dbl = true;
224	        for (int i = code.length() - 1; i >= 0; i--) {
225	            char c = code.charAt(i);
226	            if (c < '0' || c > '9') {
227	                continue;
228	            }
229	            int d = c - '0';
230	            if (dbl) {
231	                d *= 2;
232	                if (d > 9) {
233	                    d -= 9;
234	                }
235	            }
236	            sum += d;
237	            dbl = !dbl;
238	        }
239	        return (10 - (sum % 10)) % 10;
240	    }
241	
242	    /**
243	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
244	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted registration date
245	     * (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the customer code or registration
246	     * date is absent.
247	     */
248	    default String formatMembershipNumber(Owner owner) {
249	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
250	            return null;
251	        }
252	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearStart(owner.getRegistrationDate()) % 100);
253	    }
254	
255	    /**
256	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the last two digits of the
257	     * starting calendar year of the fiscal year (starting 1 July) that contains the owner's
258	     * business-day-adjusted registration date (e.g. 5 August 2026 yields {@code "FY26"} and 3 March
259	     * 2026 yields {@code "FY25"}). Returns {@code null} when the registration date is absent.
260	     */
261	    default String formatFiscalYear(Owner owner) {
262	        if (owner == null || owner.getRegistrationDate() == null) {
263	            return null;
264	        }
265	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
266	    }
267	
268	    /**
269	     * Returns the starting calendar year of the fiscal year (which starts on 1 July) that contains
270	     * the given date: the date's own year when it falls on or after 1 July, otherwise the previous
271	     * year.
272	     */
273	    private int fiscalYearStart(LocalDate date) {
274	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
275	    }
276	
277	    /**
