/**
 * Build an owner's derived duplicate-detection identity key as the lower-case SHA-256 hex digest
 * over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. A {@code null} telephone
 * or email contributes the empty string, the email is lower-cased so the comparison is
 * case-insensitive, and the last name is reduced to its Soundex code so near-identical surnames
 * collide. Two owners are duplicates only when their whole identity keys are equal.
 */
private static String identityKey(String normalizedTelephone, String email, String lastName) {
    String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
    String emailKey = email == null ? "" : email.toLowerCase();
    return hashHex(telephone + "|" + emailKey + "|" + soundex(lastName), 64, false);
}

/**
 * The American Soundex code of {@code name}: the upper-cased first letter followed by up to three
 * digits derived from the remaining letters (b,f,p,v -> 1; c,g,j,k,q,s,x,z -> 2; d,t -> 3; l -> 4;
 * m,n -> 5; r -> 6), where adjacent letters sharing a code (directly, or separated only by 'h' or
 * 'w') collapse to a single digit and vowels (a,e,i,o,u,y) act as separators, right-padded with
 * zeros to length four. A {@code null} or letter-free input yields the empty string.
 */
static String soundex(String name) {
    if (name == null) {
        return "";
    }
    StringBuilder letters = new StringBuilder();
    for (char c : name.toUpperCase().toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            letters.append(c);
        }
    }
    if (letters.length() == 0) {
        return "";
    }
    StringBuilder code = new StringBuilder().append(letters.charAt(0));
    char previous = soundexCode(letters.charAt(0));
    for (int i = 1; i < letters.length() && code.length() < 4; i++) {
        char letter = letters.charAt(i);
        char digit = soundexCode(letter);
        if (digit != '0' && digit != previous) {
            code.append(digit);
        }
        if (letter != 'H' && letter != 'W') {
            previous = digit;
        }
    }
    while (code.length() < 4) {
        code.append('0');
    }
    return code.toString();
}

/**
 * The Soundex digit for an upper-case letter, or {@code '0'} for vowels and the pass-through
 * letters (a,e,i,o,u,y,h,w) that carry no code.
 */
private static char soundexCode(char c) {
    return switch (c) {
        case 'B', 'F', 'P', 'V' -> '1';
        case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
        case 'D', 'T' -> '3';
        case 'L' -> '4';
        case 'M', 'N' -> '5';
        case 'R' -> '6';
        default -> '0';
    };
}

